const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const uid=()=> 'r_'+Math.random().toString(36).slice(2,10);
const tfName=v=>String(v).replace(/[^a-zA-Z0-9_]/g,'_').replace(/^[^a-zA-Z_]/,'r_');
const hclq=v=>JSON.stringify(String(v)).replace(/\$\{/g,()=>'$'+'$'+'{').replace(/%\{/g,'%%'+'{');
function ipv4(s){if(!/^(0|[1-9]\d{0,2})(\.(0|[1-9]\d{0,2})){3}$/.test(String(s)))return null;const p=s.split('.').map(Number);return p.some(n=>n>255)?null:p.reduce((a,n)=>a*256+n,0);}
function ipv4str(n){return [24,16,8,0].map(b=>Math.floor(n/2**b)%256).join('.');}
function cidrInfo(v){const m=String(v).match(/^([^/]+)\/(\d{1,2})$/);if(!m)return null;const ip=ipv4(m[1]),prefix=Number(m[2]);if(ip===null||prefix>32)return null;const size=2**(32-prefix),start=Math.floor(ip/size)*size;return {ip,prefix,start,end:start+size-1,size,canonical:ipv4str(start)+'/'+prefix};}
const contains=(c,ip)=>{const x=typeof c==='string'?cidrInfo(c):c,n=typeof ip==='string'?ipv4(ip):ip;return !!x&&n!==null&&n>=x.start&&n<=x.end;};
const overlaps=(a,b)=>{a=typeof a==='string'?cidrInfo(a):a;b=typeof b==='string'?cidrInfo(b):b;return !!a&&!!b&&a.start<=b.end&&b.start<=a.end;};
function usableIp(ip,c){const a=cidrInfo(c),n=ipv4(ip);return !!a&&n!==null&&n>=a.start+2&&n<a.end;}
