function normalizeCatalog(raw,region){
const toArr=x=>Array.isArray(x)?x:x?.data||[];let arr=toArr(raw),shapes=[],images=[];
if(raw.shapes)shapes=toArr(raw.shapes);if(raw.images)images=toArr(raw.images);
if(arr.length){if(arr[0].shape||arr[0]['shape-name'])shapes=arr;else if(arr[0]['operating-system']||arr[0].operatingSystem)images=arr;else throw Error('Use JSON de shape list ou image list.');}
const pick=(o,a,b)=>o[a]??o[b],num=(o,a,b,f)=>Number(pick(o,a,b)??f);
shapes=shapes.filter(x=>typeof(x.shape||x['shape-name'])==='string').map(x=>{const name=x.shape||x['shape-name'],oc=pick(x,'ocpu-options','ocpuOptions')||{},mo=pick(x,'memory-options','memoryOptions')||{},flex=pick(x,'is-flexible','isFlexible')??name.endsWith('.Flex');return {name,kind:name.startsWith('BM.')?'BM':'VM',family:name.includes('GPU')?'GPU':name.includes('DenseIO')?'DenseIO':/HPC|Optimized/.test(name)?'HPC / Optimized':'Standard',arch:/[Aa]mpere|[Aa]rm|[Aa]arch|[Gg]race/.test(x['processor-description']||x.processorDescription||'')||/Standard\.A[124]|GB[23]00/.test(name)?'aarch64':'x86_64',vendor:x['processor-description']||x.processorDescription||'OCI',flex,ocpus:num(x,'ocpus','ocpus',1),memory:num(x,'memory-in-gbs','memoryInGBs',16),maxOcpus:Number(oc.max??x.ocpus??1),minOcpus:Number(oc.min??1),maxMemory:Number(mo['max-in-g-bs']??mo.maxInGBs??mo['max-in-gbs']??x['memory-in-gbs']??x.memoryInGBs??16),memoryOptions:mo,source:'tenancy',legacy:false,region,windows:!(/Standard\.A[124]|GB[23]00/.test(name))};});
images=images.filter(x=>typeof x.id==='string'&&x.id.startsWith('ocid1.image.')).map(x=>{const name=pick(x,'display-name','displayName')||x.id;return {key:x.id,id:x.id,name,os:pick(x,'operating-system','operatingSystem')||'Custom',version:pick(x,'operating-system-version','operatingSystemVersion')||'',arch:/aarch64|arm64/i.test(name)?'aarch64':'x86_64',source:'tenancy',region,compartmentId:pick(x,'compartment-id','compartmentId')||'',compatibleShape:raw.compatibleShape||''};});
if(!shapes.length&&!images.length)throw Error('Nenhum shape ou imagem reconhecido.');
return {shapes,images,region:raw.region||region,importedAt:new Date().toISOString()};
}

