const asBytes=v=>v instanceof Uint8Array?v:new Uint8Array(v);
function bytesBase64(value){const bytes=asBytes(value);let result='';for(let i=0;i<bytes.length;i+=8192)result+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(result);}
function base64urlBytes(value){const text=atob(value.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(text,c=>c.charCodeAt(0));}
function joinBytes(...arrays){const len=arrays.reduce((n,a)=>n+a.length,0),result=new Uint8Array(len);let offset=0;for(const a of arrays){result.set(a,offset);offset+=a.length;}return result;}
function sshString(bytes){bytes=asBytes(bytes);const header=new Uint8Array(4);new DataView(header.buffer).setUint32(0,bytes.length,false);return joinBytes(header,bytes);}
function sshMpint(bytes){bytes=asBytes(bytes);while(bytes.length>1&&bytes[0]===0)bytes=bytes.slice(1);if(bytes[0]&128)bytes=joinBytes(new Uint8Array([0]),bytes);return sshString(bytes);}
async function generateSshPair(username,bits=3072,engine=globalThis.crypto){
if(!engine?.subtle)throw Error('Web Crypto indisponível. Abra a ferramenta em HTTPS ou em um navegador compatível com arquivo HTML local.');
if(![3072,4096].includes(Number(bits)))throw Error('Tamanho RSA inválido.');
const pair=await engine.subtle.generateKey({name:'RSASSA-PKCS1-v1_5',modulusLength:Number(bits),publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['sign','verify']);
const jwk=await engine.subtle.exportKey('jwk',pair.publicKey),privateBytes=await engine.subtle.exportKey('pkcs8',pair.privateKey);
const payload=joinBytes(sshString(new TextEncoder().encode('ssh-rsa')),sshMpint(base64urlBytes(jwk.e)),sshMpint(base64urlBytes(jwk.n)));
const comment=String(username||'clouduser').replace(/[^a-zA-Z0-9_-]/g,'')+'@oci-architect';
const publicKey='ssh-rsa '+bytesBase64(payload)+' '+comment;
const body=bytesBase64(privateBytes).match(/.{1,64}/g).join('\n');
const privatePem='-----BEGIN PRIVATE KEY-----\n'+body+'\n-----END PRIVATE KEY-----\n';
const fingerprint='SHA256:'+bytesBase64(await engine.subtle.digest('SHA-256',payload)).replace(/=+$/,'');
return {publicKey,privatePem,fingerprint,bits:Number(bits),username:comment.split('@')[0],createdAt:new Date().toISOString()};
}
