    push('oci_core_vcn',id,['compartment_id = '+comp,'display_name = '+hclq(node.name),'cidr_blocks = ['+hclq(node.cidr)+']']);
    push('oci_core_drg_route_distribution',id,['drg_id = oci_core_drg.lab_drg.id','distribution_type = "IMPORT"','display_name = '+hclq('import-'+id)]);
    for(const [idx,target]of drgRoutesFor(net,node).filter(t=>t.targetId!=='onprem').entries())push('oci_core_drg_route_distribution_statement',id+'_'+idx,['drg_route_distribution_id = oci_core_drg_route_distribution.'+id+'.id','action = "ACCEPT"','priority = '+(10+idx),'match_criteria {\n    match_type = "DRG_ATTACHMENT_ID"\n    drg_attachment_id = oci_core_drg_attachment.'+tfName(target.targetId)+'.id\n  }']);
    push('oci_core_drg_route_table',id,['drg_id = oci_core_drg.lab_drg.id','import_drg_route_distribution_id = oci_core_drg_route_distribution.'+id+'.id','display_name = '+hclq('routes-'+id)]);
    if(node.attached)push('oci_core_drg_attachment',id,['drg_id = oci_core_drg.lab_drg.id','drg_route_table_id = oci_core_drg_route_table.'+id+'.id','network_details {\n    id = oci_core_vcn.'+id+'.id\n    type = "VCN"\n    vcn_route_type = "VCN_CIDRS"\n  }']);
