    const rules=[],protocol=net.protocol==='TCP'?'6':net.protocol==='UDP'?'17':'1',option=net.protocol==='TCP'?'tcp_options':net.protocol==='UDP'?'udp_options':'';
    if(node.egress!==false)rules.push('egress_security_rules {\n    protocol = '+hclq(protocol)+'\n    destination = "0.0.0.0/0"\n    stateless = '+stateless+'\n  }');
    const ingress=(other,port)=>'ingress_security_rules {\n    protocol = '+hclq(protocol)+'\n    source = '+hclq(other.cidr)+'\n    source_type = "CIDR_BLOCK"\n    stateless = '+stateless+(option?'\n    '+option+' {\n      min = '+port+'\n      max = '+port+'\n    }':'')+'\n  }';
