    if(stateless)rules.push('ingress_security_rules {\n    protocol = "1"\n    source = "0.0.0.0/0"\n    source_type = "CIDR_BLOCK"\n    stateless = true\n    icmp_options {\n      type = 3\n      code = 4\n    }\n  }');
    push('oci_core_security_list',id,['compartment_id = '+comp,'vcn_id = oci_core_vcn.'+id+'.id',...rules]);
