// Presentation state stays in the tab; resource values keep the existing backup format.
let builderStep='service';
function builderFieldGroups(type){
  const accessKeys=new Set(['subnet','subnetCidr','privateIp','publicIp','reservedPublicIp','nsgIds','vcn','routeTable','drg','target']);
  const fields=TYPES[type].fields.filter(f=>f.type!=='heading'&&(f.key!=='guestOs'||imageFor(draft,s)?.os==='Custom'));
  return {config:fields.filter(f=>!accessKeys.has(f.key)),access:fields.filter(f=>accessKeys.has(f.key))};
}
function builderSteps(){
  if(selectedType==='universal')return [{id:'service',label:'Serviço'},{id:'config',label:'Editor HCL'}];
  const steps=[{id:'service',label:'Serviço'},{id:'config',label:'Configuração'}];
  if(builderFieldGroups(selectedType).access.length||selectedType==='compute')steps.push({id:'access',label:'Rede e acesso'});
  if(selectedType==='compute')steps.push({id:'init',label:'Inicialização'});
  steps.push({id:'review',label:'Revisão'});return steps;
}
function builderFieldsHtml(fields){
  if(selectedType==='compute'&&fields.some(f=>f.key==='image'))return computeConfigurationHtml(fields);
  const advanced=new Set(['ad','kmsKey','nsgIds','namespace']);
  const basic=fields.filter(f=>!advanced.has(f.key)),extra=fields.filter(f=>advanced.has(f.key));
  return (basic.length?'<div class="fields">'+basic.map(f=>renderField(f,draft)).join('')+'</div>':'')+
    (extra.length?'<details class="advanced-settings"><summary>Opções avançadas <span>'+extra.length+(extra.length===1?' campo':' campos')+'</span></summary><div class="fields">'+extra.map(f=>renderField(f,draft)).join('')+'</div></details>':'');
}
