    (selectedType==='universal'?'<div class="notice">Use o editor para informar o HCL e as policies específicas do serviço.</div><button type="button" class="button primary" data-action="universal">'+icon('code')+'Abrir editor universal</button>':builderFieldsHtml(groups.config)||'<div class="notice">Este serviço usa o nome, a região e o compartimento do projeto. Continue para revisar.</div>')+'<div id="license-notice" class="license-notice"></div></section>'+
    '<section class="wizard-pane" data-step-pane="access"><h3 class="step-title" tabindex="-1">Rede e acesso</h3><p class="step-description">Associe as dependências e configure o acesso ao recurso.</p>'+builderFieldsHtml(groups.access)+'<div id="linux-access-panel" class="linux-access-panel"></div>'+(selectedType==='compute'&&guestFamily(draft,s)==='WINDOWS'?'<div class="notice">Acesso Windows via RDP. Revise a conectividade e as regras de segurança do ambiente.</div>':'')+'</section>'+
    (selectedType==='compute'?'<section class="wizard-pane" data-step-pane="init"><h3 class="step-title" tabindex="-1">Inicialização da VM</h3><p class="step-description">Escolha os ajustes do primeiro boot e revise o script antes de exportar.</p><div id="initialization-panel"></div></section>':'')+
    '<section class="wizard-pane" data-step-pane="review"><h3 class="step-title" tabindex="-1">Revise antes de adicionar</h3><p class="step-description">Confira os dados, as tags e as pendências para o Terraform.</p><div id="resource-review"></div></section>';
  $('resource-form').noValidate=true;
  renderSelectedPolicies();renderFormHints();renderLinuxAccess();renderInitializationPanel();renderLicenseNotice();syncProjectControls();applyBuilderStep();
