  document.documentElement.style.setProperty('--read-scale',String(a.fontScale||1));document.documentElement.style.setProperty('--ui-font',UI_FONT_OPTIONS.find(x=>x.id===a.fontFamily)?.css||UI_FONT_OPTIONS[0].css);document.documentElement.style.setProperty('--code-font',CODE_FONT_OPTIONS.find(x=>x.id===a.codeFont)?.css||CODE_FONT_OPTIONS[0].css);document.documentElement.dataset.density=a.density||'comfortable';document.documentElement.style.setProperty('--text-leading',String(a.lineHeight||1.6));document.documentElement.style.setProperty('--text-tracking',String(a.letterSpacing||0)+'em');document.documentElement.style.setProperty('--reading-code-size',String(a.codeSize||12)+'px');updateReadingControls();
