function refreshIamStudio(){
  const rows=activePolicyRows(),audit=iamAudit(s,rows,iamSelectedResources());if(!$('iam-code'))return;
  $('iam-code').innerHTML=rows.length?rows.map(x=>esc(x.text).replace(/\b(Allow|to|in|where|ALL|ANY)\b/g,'<span class="iam-keyword">$1</span>').replace(/\b(inspect|read|use|manage)\b/g,'<span class="iam-verb">$1</span>')).join('\n\n'):'# Selecione um serviço ou adicione recursos ao plano.';
  $('iam-total').textContent=String(rows.length);$('iam-issue-count').textContent=String(audit.errors.length+audit.warnings.length);
  $('iam-ready-badge').className='badge '+(audit.errors.length?'warning':'mint');$('iam-ready-badge').textContent=rows.length?(audit.errors.length?'PREENCHER / CORRIGIR':'GERADO · CONFERÊNCIA LOCAL'):'SELECIONE UM SERVIÇO';
  $('iam-bundle-notes').textContent=iamView==='service'?policyGuidance(iamService):'Statements consolidados por principal, tipo, condição e escopo. O pacote policies.tf é independente do main.tf.';
  $('iam-metrics').innerHTML=[[rows.length,'Statements gerados'],[rows.filter(x=>!x.principal?.startsWith('service ')&&x.category!=='manual').length,'Permissões do principal'],[audit.services,'Permissões de serviços'],[audit.errors.length,'Pendências locais']].map(([n,label])=>'<div><strong>'+n+'</strong><span>'+label+'</span></div>').join('');
  $('iam-reasons').innerHTML=rows.map((row,i)=>'<article class="iam-dependency-row"><div class="iam-dependency-top"><span class="statement-index">'+String(i+1).padStart(2,'0')+'</span><strong>'+esc(row.verb+' '+row.type)+'</strong><span class="badge">'+esc(row.category==='kms'?'KMS':row.category==='manual'?'MANUAL':row.category==='tag'?'TAGS':row.category==='dependency'?'DEPENDÊNCIA':'RECURSO')+'</span></div><div class="iam-dependency-meta"><span>Principal</span><code>'+esc(row.principal||'Informado no statement')+'</code><span>Escopo</span><code>'+esc(row.scope)+'</code></div><p>'+row.reasons.map(esc).join('<br>')+'</p>'+(row.condition?'<code class="iam-condition">where '+esc(row.condition)+'</code>':'')+'<a class="text-button" href="'+esc(row.source||IAM_DOCS.syntax)+'" target="_blank" rel="noopener">Referência Oracle '+icon('arrow')+'</a></article>').join('')||'<p class="muted">Selecione um serviço para ver as dependências.</p>';
  const groups=[['error','Pendências para corrigir'],['warning','Pontos para revisar'],['info','Limites e contexto']];
  $('iam-audit').innerHTML='<div class="iam-audit-heading"><span class="badge '+(audit.errors.length?'warning':'mint')+'">'+(audit.errors.length?'HÁ PENDÊNCIAS LOCAIS':'SEM ERROS LOCAIS DETECTADOS')+'</span><p>Referências revisadas em 23/10/2026. A análise verifica os valores e as regras implementadas no HTML; não consulta permissões na tenancy.</p></div>'+groups.map(([level,title])=>{const list=audit.issues.filter(x=>x.level===level);return list.length?'<section class="iam-audit-group '+level+'"><h3>'+title+' <span class="count">'+list.length+'</span></h3><ul>'+list.map(x=>'<li>'+esc(x.message)+'</li>').join('')+'</ul></section>':'';}).join('');
  $('iam-manual-list').innerHTML=s.iam.custom.map((x,i)=>'<div class="manual-policy-row"><code>'+esc(x.verb+' '+x.type)+'</code><button class="icon-button" data-action="remove-policy" data-index="'+i+'" aria-label="Remover statement '+(i+1)+'">'+icon('trash')+'</button></div>').join('');
  setIamOutputTab(iamOutputTab);
}
