function chatgptThemeForLegacy(raw){
 if(themes.some(t=>t.id===raw.theme))return raw.theme;
 if(RETIRED_SPECIAL_THEME_IDS.includes(raw.theme))return raw.theme.endsWith('-light')?'chatgpt-light':'chatgpt-dark';
 const aliases={'ayu-mirage':'ayu-dark','oracle-redwood-light':'oracle-light','oracle-redwood-dark':'oracle-dark','monokai':'monokai-dark','vscode-dark-plus':'vscode-dark','vscode-light-plus':'vscode-light','tokyo-night':'tokyo-night-dark','nord':'nord-dark','catppuccin-mocha':'catppuccin-dark','catppuccin-latte':'catppuccin-light','dracula':'dracula-dark','github-dark-dimmed':'github-dark','github-dark-high-contrast':'github-dark','github-light-high-contrast':'github-light'};if(aliases[raw.theme])return aliases[raw.theme];
 const custom=(Array.isArray(raw.customThemes)?raw.customThemes:[]).find(t=>t?.id===raw.theme);
 return custom?.mode==='light'||/(?:light|white|latte|dawn|dayfox|lotus|operandi)/i.test(String(raw.theme||''))?'chatgpt-light':'chatgpt-dark';
}
function migrateChatgptAppearance(state,raw){
 state.theme=chatgptThemeForLegacy(raw);state.customThemes=[];delete state.specialAccents;
 if(![1,2,3,4].includes(raw.themeCatalogVersion)||!themes.some(t=>t.id===raw.theme)){state.accent='';state.accentPreset='default';}
 else{state.accentPreset=CHATGPT_ACCENTS.some(a=>a.id===raw.accentPreset)?raw.accentPreset:'default';state.accent=/^#[a-f0-9]{6}$/i.test(raw.accent||'')?raw.accent:'';if(state.accentPreset==='custom'&&!state.accent)state.accentPreset='default';}
 state.themeCatalogVersion=4;state.defaultThemeVersion=2;
}
function colorLuminance(hex){return [1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4).reduce((sum,x,i)=>sum+x*[.2126,.7152,.0722][i],0);}
function colorContrast(a,b){const x=colorLuminance(a),y=colorLuminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
function readableChatgptAccent(color,theme){
 let result=color;const target=theme.mode==='dark'?255:0,surfaces=[theme.bg,theme.sidebar,theme.panel,theme.tokens.raised];
 for(let i=0;i<36&&Math.min(...surfaces.map(bg=>colorContrast(result,bg)))<4.5;i++)result='#'+[1,3,5].map(at=>Math.round(parseInt(result.slice(at,at+2),16)*.88+target*.12).toString(16).padStart(2,'0')).join('');
 return result;
}
function getThemeAccentChoice(){return {preset:s.accentPreset,custom:s.accent};}
function writeThemeAccent(preset,custom=''){s.accentPreset=preset;s.accent=custom;}
function currentChatgptAccent(theme=themes.find(t=>t.id===s.theme)||themes[0]){const choice=getThemeAccentChoice(theme),preset=CHATGPT_ACCENTS.find(a=>a.id===choice.preset)||CHATGPT_ACCENTS[0];return preset.id==='default'?theme.accent:preset.id==='custom'&&/^#[a-f0-9]{6}$/i.test(choice.custom)?choice.custom:preset[theme.mode]||theme.accent;}
function updateAccentControls(){
 const theme=themes.find(t=>t.id===s.theme)||themes[0],preset=CHATGPT_ACCENTS.find(a=>a.id===getThemeAccentChoice(theme).preset)||CHATGPT_ACCENTS[0],color=currentChatgptAccent(theme);
 if($('accent-picker')&&$('accent-picker').value.toLowerCase()!==color.toLowerCase())$('accent-picker').value=color;
 if($('accent-hex'))$('accent-hex').textContent=color.toUpperCase();
 if($('custom-accent-field'))$('custom-accent-field').hidden=preset.id!=='custom';
 const swatches=$('accent-swatches');if(swatches){
  if(!swatches.children.length)swatches.innerHTML=CHATGPT_ACCENTS.map(a=>'<button type="button" class="accent-swatch" data-action="accent-swatch" data-accent="'+a.id+'" aria-label="'+esc(a.name)+'" title="'+esc(a.name)+'"><span aria-hidden="true"></span></button>').join('');
  for(const button of swatches.children){const a=CHATGPT_ACCENTS.find(x=>x.id===button.dataset.accent);button.setAttribute('aria-pressed',String(a.id===preset.id));button.style.setProperty('--swatch-color',a.id==='default'?theme.accent:a.id==='custom'?'conic-gradient(#ff8c7b,#f3c16d,#6fd5c6,#75beff,#aaa4ff,#ff8c7b)':a.sample);}
 }

}
