function themedCard(theme){const accent=readableChatgptAccent(currentChatgptAccent(theme),theme),ink=readableAccentInk(accent);const preview=' style="background:'+theme.bg+';color:'+theme.tokens.text+';border-color:'+theme.tokens.border+'"';return '<article class="theme-shell"><button type="button" class="theme-card chatgpt-theme-card '+(s.theme===theme.id?'selected':'')+'" data-action="theme" data-id="'+theme.id+'" aria-labelledby="theme-title-'+theme.id+'" aria-describedby="theme-description-'+theme.id+'" aria-pressed="'+(s.theme===theme.id)+'"><div class="theme-preview chatgpt-preview"'+preview+'><div class="theme-mini-sidebar" style="background:'+theme.sidebar+'"><span class="chatgpt-mini-mark" style="border-color:'+theme.tokens.border+'"></span><i style="background:'+theme.tokens.muted+'"></i><i style="background:'+theme.tokens.muted+'"></i><i style="background:'+theme.tokens.muted+'"></i></div><div class="theme-mini-main"><strong>OCI Studio</strong><div class="chatgpt-mini-message" style="background:'+theme.tokens.raised+'"></div><div class="chatgpt-mini-line" style="background:'+theme.tokens.muted+'"></div><div class="chatgpt-mini-composer" style="background:'+theme.tokens.raised+';border-color:'+theme.tokens.border+'"><span style="background:'+accent+';color:'+ink+'">↑</span></div></div></div><div class="chatgpt-card-heading"><h3 id="theme-title-'+theme.id+'">'+esc(theme.name)+'</h3><span class="theme-choice-indicator" aria-hidden="true">'+(s.theme===theme.id?'✓':'')+'</span></div><p id="theme-description-'+theme.id+'">'+esc(theme.desc)+'</p></button></article>';}
function renderThemeGallery(){const active=themes.find(t=>t.id===s.theme)||themes[0],grid=$('theme-grid');const modeHeading=document.querySelector('.chatgpt-mode-heading');if(modeHeading)modeHeading.hidden=themes.filter(t=>t.familyKey===active.familyKey).length<2;if(grid)grid.innerHTML=themes.filter(t=>t.familyKey===active.familyKey).map(themedCard).join('');if($('theme-family-name'))$('theme-family-name').textContent=active.family;updateThemeOverview();}
