function configuredBootstrapScript(v){
  const b=bootstrapSettings(v),lines=bootstrapEnvironment(v).map(entry=>{const pos=entry.indexOf('=');return 'export '+entry.slice(0,pos)+'='+shellQuote(entry.slice(pos+1));});
  if(b.bootstrapMode!=='apply')lines.push('if (( $# == 0 )); then set -- --'+b.bootstrapMode+'; fi');
  return '#!/bin/bash\n# OCI Architect Studio: parametros do formulario; corpo original abaixo.\n'+lines.join('\n')+'\n'+ORACLE_BOOTSTRAP.source.replace(/^#![^\n]*\n/,'');
}

