  const colors={panel:color('panel','#181e25'),input:color('input','#11161c'),text:color('text','#e8edf3'),muted:color('muted','#a4adb9'),border:color('border','#343b45'),ok:color('mint','#90d7bb'),bad:color('danger','#ef8d8d'),accent:color('accent','#ef956f')};
