  const position=id=>positions.get(id)||center;
  const path=(id,towardCenter,offset=0)=>{const p=position(id),edge=p.x<center.x?p.x+118:p.x-118,cx=p.x<center.x?center.x-67:center.x+67,mid=(edge+cx)/2;return towardCenter?'M'+edge+' '+(p.y+offset)+' H'+mid+' V'+(center.y+offset)+' H'+cx:'M'+cx+' '+(center.y+offset)+' H'+mid+' V'+(p.y+offset)+' H'+edge;};
  for(const node of nodes)svg+='<path d="'+path(node.id,true)+'" fill="none" stroke="'+esc(colors.border)+'" stroke-width="2"'+(!node.attached?' stroke-dasharray="6 6"':'')+'/>';
  if(flow){
    const first=flow.steps.find(x=>x.status==='blocked'),beforeDrg=first&&['egress','vcn','source-attachment'].includes(first.id),atDrg=first?.id==='drg';
    svg+='<path d="'+path(flow.fromId,true,-7)+'" fill="none" stroke="'+esc(beforeDrg?colors.bad:colors.ok)+'" stroke-width="4" marker-end="url(#route-arrow)"/>';
    if(!beforeDrg&&!atDrg)svg+='<path d="'+path(flow.toId,false,7)+'" fill="none" stroke="'+esc(first?colors.bad:colors.ok)+'" stroke-width="4" marker-end="url(#route-arrow)"/>';
  }
  const drgBlocked=flow?.steps.find(x=>x.status==='blocked')?.id==='drg';
  svg+='<rect x="393" y="'+(center.y-45)+'" width="134" height="90" rx="13" fill="'+esc(colors.input)+'" stroke="'+esc(drgBlocked?colors.bad:colors.accent)+'" stroke-width="2"/><text x="460" y="'+(center.y-7)+'" text-anchor="middle" fill="'+esc(colors.text)+'" font-family="system-ui,sans-serif" font-size="19" font-weight="700">DRG v2</text><text x="460" y="'+(center.y+16)+'" text-anchor="middle" fill="'+esc(colors.muted)+'" font-family="system-ui,sans-serif" font-size="13">'+esc(flow?'Entrada: '+flow.fromId:'Hub de roteamento')+'</text>';
  for(const node of nodes){const p=position(node.id),role=flow?.fromId===node.id?'ORIGEM':flow?.toId===node.id?'DESTINO':node.id==='onprem'?'CONEXÃO EXTERNA':'VCN',selected=routeInspectId===node.id;
    svg+='<g class="route-map-node" tabindex="0" role="button" data-action="inspect-route-node" data-id="'+esc(node.id)+'" aria-label="Inspecionar tabelas de '+esc(node.name)+'"><rect x="'+(p.x-118)+'" y="'+(p.y-40)+'" width="236" height="80" rx="10" fill="'+esc(colors.input)+'" stroke="'+esc(selected?colors.accent:colors.border)+'" stroke-width="'+(selected?2:1)+'"/><circle cx="'+(p.x-102)+'" cy="'+(p.y-24)+'" r="3" fill="'+esc(node.attached?colors.ok:colors.bad)+'"/><text x="'+(p.x-91)+'" y="'+(p.y-20)+'" fill="'+esc(colors.muted)+'" font-family="system-ui,sans-serif" font-size="9" letter-spacing="1">'+role+'</text><text x="'+(p.x-102)+'" y="'+(p.y+2)+'" fill="'+esc(colors.text)+'" font-family="system-ui,sans-serif" font-size="14" font-weight="600">'+esc(node.name.length>27?node.name.slice(0,26)+'…':node.name)+'</text><text x="'+(p.x-102)+'" y="'+(p.y+24)+'" fill="'+esc(colors.muted)+'" font-family="ui-monospace,monospace" font-size="15">'+esc(node.cidr)+'</text></g>';
  }
  if(flow){const from=position(flow.fromId),to=position(flow.toId);svg+='<text x="'+from.x+'" y="'+(from.y-50)+'" text-anchor="middle" fill="'+esc(colors.ok)+'" font-family="ui-monospace,monospace" font-size="11">'+esc(routeDirection==='reverse'?net.destination:net.source)+'</text><text x="'+to.x+'" y="'+(to.y-50)+'" text-anchor="middle" fill="'+esc(colors.ok)+'" font-family="ui-monospace,monospace" font-size="11">'+esc(flow.targetIp)+'</text>';}
  return svg+'</svg>';
