 obj(raw,'projeto');safe(raw,'projeto');const base=defaults();for(const [k,v]of Object.entries(base)){if(!Object.hasOwn(raw,k))continue;if(typeof v==='string')str(raw[k],k);else if(typeof v==='boolean'&&typeof raw[k]!=='boolean')fail(k);else if(typeof v==='number')num(raw[k],k);}
