 if(raw.iam!==undefined){obj(raw.iam,'iam');for(const [k,v]of Object.entries(base.iam))if(Object.hasOwn(raw.iam,k)&&typeof v==='string')str(raw.iam[k],'iam.'+k);if(raw.iam.custom!==undefined){if(!Array.isArray(raw.iam.custom)||raw.iam.custom.length>1000)fail('iam.custom');for(const row of raw.iam.custom){obj(row,'statement');for(const key of ['verb','type','condition'])if(row[key]!==undefined)str(row[key],'statement.'+key);if(!['inspect','read','use','manage'].includes(row.verb)||!/^[a-z0-9-]+$/.test(row.type||''))fail('statement');}}}
