document.addEventListener('click',async e=>{
  const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  if(action==='inspect-windows')inspectWindowsScript();
  if(action==='close-windows-script')$('windows-script-dialog').close();
  if(action==='windows-script-tab')showWindowsScript(button.dataset.tab);
  if(action==='copy-windows-script')await copy($('windows-script-code').textContent);
  if(action==='download-windows-script'){
    if(!button.closest('dialog'))draft=gatherDraft();
    const errors=validateResource({...builderResource(),values:{...draft,winBootstrapEnabled:true}},s).filter(x=>/bootstrap Windows|Windows Server|Fuso Windows|Metadados Windows/i.test(x));
    if(errors.length){toast(errors[0]);return;}
    download('oci-windows-'+windowsBootstrapSettings(draft).winBootstrapMode.toLowerCase()+'.ps1',configuredWindowsScript(draft),'text/plain;charset=utf-8');
    toast('Script PowerShell baixado. Execute como Administrador no Windows Server selecionado.');
  }
});
