$('tag-form').addEventListener('submit',event=>{
  event.preventDefault();const kind=$('tag-kind').value,tag={kind,key:$('tag-key').value.trim(),value:$('tag-value').value,...(kind==='defined'?{namespace:$('tag-namespace').value.trim()}:{})};
  const duplicate=s.tags.findIndex((t,i)=>i!==tagEditIndex&&tagIdentity(t)===tagIdentity(tag));if(duplicate>=0){toast('Essa chave já existe. Use Editar para alterar o valor.');return;}
  const tags=clone(s.tags);if(tagEditIndex>=0)tags[tagEditIndex]=tag;else tags.push(tag);const index=tagEditIndex>=0?tagEditIndex:tags.length-1,audit=tagAudit({...s,tags}),errors=audit.errors.filter(x=>x.index===undefined||x.index===index);if(errors.length){toast(errors[0].message);return;}
  s.tags=tags;resetTagEditor();updateAll();toast('Tag salva no projeto.');
});
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  if(action==='edit-tag')editTag(Number(button.dataset.index));
  if(action==='cancel-tag-edit')resetTagEditor();
  if(action==='focus-tag-standard'){
    const row=tagProfileRows(s).find(t=>tagIdentity(t)===button.dataset.identity),index=s.tags.findIndex(t=>tagIdentity(t)===button.dataset.identity);if(index>=0)editTag(index);else if(row){resetTagEditor();$('tag-kind').value=row.kind;$('tag-namespace').value=row.namespace||'';$('tag-namespace').disabled=row.kind!=='defined';$('tag-key').value=row.key;$('tag-value').value=row.value;updateTagValueOptions();$('tag-value').focus();$('tag-editor-title').scrollIntoView({behavior:'smooth',block:'center'});}
  }
  if(action==='apply-tag-standard'){try{const result=addMissingStandard(s);s.tags=result.tags;resetTagEditor();updateAll();toast(result.added?result.added+' chave(s) adicionada(s). Preencha equipe e centro de custo.':'Todas as chaves desse padrão já estão cadastradas.');}catch(error){toast(error.message);}}
  if(action==='open-tag-import'){$('tag-import-dialog').showModal();tagImportReview=null;$('tag-import-preview').innerHTML='';$('apply-tag-import').disabled=true;}
  if(action==='close-tag-import')$('tag-import-dialog').close();
  if(action==='preview-tag-import')previewTagImport();
  if(action==='apply-tag-import'){
    if(!tagImportReview||tagImportReview.input!==$('tag-import-json').value||tagImportReview.overwrite!==$('tag-import-overwrite').checked||tagImportReview.baseline!==JSON.stringify(s.tags)){toast('Confira a importação novamente; os dados mudaram.');return;}
    try{const result=mergeImportedTags(s,tagImportReview.rows,tagImportReview.overwrite);s.tags=result.tags;tagImportReview=null;$('tag-import-dialog').close();resetTagEditor();updateAll();toast('Tags importadas: '+result.added+' nova(s), '+result.updated+' atualizada(s).');}catch(error){toast(error.message);}
  }
  if(action==='download-tags'){if(blockInvalidTags())return;download('tags-'+($('tag-json-format').value==='api'?'oci-api':'terraform')+'.json',JSON.stringify(currentTagsJson(),null,2),'application/json');}
  if(action==='route-direction'){routeDirection=button.dataset.direction==='reverse'?'reverse':'forward';routeInspectId=selectedRouteFlow()?.fromId||routeInspectId;renderTopology();renderRouteResult();renderRouteInspector();}
  if(action==='inspect-route-node'){routeInspectId=button.dataset.id;renderRouteInspector();renderTopology();}
  if(action==='swap-route'){[s.network.source,s.network.destination]=[s.network.destination,s.network.source];renderNetwork();save();}
  if(action==='download-route-map'){download('mapa-rotas-'+(routeDirection==='reverse'?'retorno':'ida')+'.svg',routeMapSvg(),'image/svg+xml;charset=utf-8');}
  if(action==='download-route-report')download('diagnostico-rotas.json',JSON.stringify({tool:'OCI Architect Studio',modelVersion:7,generatedAt:new Date().toISOString(),scope:'Simulação local IPv4; sem consulta à OCI e sem envio de pacotes.',network:s.network,result:simulateRoute(s.network)},null,2),'application/json');
});
document.addEventListener('input',event=>{
  const element=event.target;if(element.id==='tag-search')renderTagList();
  if(['tag-key','tag-namespace','tag-kind'].includes(element.id))updateTagValueOptions();
  if(['tag-import-json','tag-import-overwrite'].includes(element.id)){tagImportReview=null;$('apply-tag-import').disabled=true;$('tag-import-preview').innerHTML='<p class="small muted">Confira novamente para revisar os dados alterados.</p>';}
});
document.addEventListener('change',event=>{
  const element=event.target;
  if(element.id==='tag-profile'){s.tagProfile=element.value;renderTags();save();}
  if(element.id==='tag-filter')renderTagList();
  if(element.id==='tag-json-format')$('tags-code').textContent=JSON.stringify(currentTagsJson(),null,2);
  if(element.id==='route-inspect-node'){routeInspectId=element.value;renderTopology();renderRouteInspector();}
  if(['f-net-protocol','f-net-securityMode'].includes(element.id)){s.network[element.name.slice(4)]=element.value;renderNetwork();save();}
  if(element.dataset.importNode){const node=networkNodes(s.network).find(n=>n.id===element.dataset.importNode),ids=networkNodes(s.network).filter(n=>n.id!==node.id).map(n=>n.id),current=new Set(importedIds(node).length?importedIds(node):ids);if(element.checked)current.add(element.dataset.importTarget);else current.delete(element.dataset.importTarget);node.importFrom=[...current].filter(id=>id!=='none').join(',')||'none';refreshNetwork();save();}
});
