 button.addEventListener('click',()=>{if(menu.hidden)open();else close();});
 button.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();open();}if(e.key==='Escape')close(true);});
