 menu.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close(true);return;}const choices=[...menu.querySelectorAll('[data-language]')],at=choices.indexOf(document.activeElement);let next;if(e.key==='ArrowDown')next=(at+1)%choices.length;if(e.key==='ArrowUp')next=(at-1+choices.length)%choices.length;if(e.key==='Home')next=0;if(e.key==='End')next=choices.length-1;if(next!==undefined){e.preventDefault();choices[next].focus();}});
 document.addEventListener('click',e=>{if(!control.contains(e.target))close();});
